function payloadFromShape(shape: KpiDataShape, index: number, title: string): KpiPreviewPayload {
  if (shape === "single-value") {
    return { shape, title, value: 60 + (index % 37), unit: "%", delta: (index % 9) - 2 };
  }
  if (shape === "timeseries") {
    return {
      shape,
      title,
      points: [0, 1, 2, 3, 4, 5].map((offset) => 24 + ((index + offset * 3) % 61)),
      labels: ["-5", "-4", "-3", "-2", "-1", "now"],
      delta: ((index % 17) - 8) / 2
    };
  }
  if (shape === "table") {
    return {
      shape,
      title,
      columns: ["owner", "score", "eta"],
      rows: [
        { owner: "A", score: 70 + (index % 20), eta: `${2 + (index % 6)}h` },
        { owner: "B", score: 62 + (index % 18), eta: `${1 + (index % 4)}h` },
        { owner: "C", score: 55 + (index % 22), eta: `${3 + (index % 5)}h` }
      ]
    };
  }
  if (shape === "events") {
    return {
      shape,
      title,
      events: [
        { at: "09:10", text: `event-${index}-open`, severity: "info" },
        { at: "09:14", text: `event-${index}-review`, severity: "warn" },
        { at: "09:18", text: `event-${index}-close`, severity: "critical" }
      ]
    };
  }
  return {
    shape: "ratio",
    title,
    numerator: 50 + (index % 40),
    denominator: 100,
    value: 50 + (index % 40),
    unit: "%",
    delta: ((index % 11) - 5) / 2
  };
}

function snippetFor(id: string, title: string): string {
  return [
    "import { KpiCard } from \"@hitech/ui-kit\";",
    "",
    "export function ExampleKpiTile() {",
    `  return <KpiCard catalogId="${id}" title="${title}" dataProvider="mock" />;`,
    "}"
  ].join("\n");
}

function toCatalogItem(seed: BulkSeed, index: number): KpiCatalogItem {
  const [idSlug, title, intent, shape, maturity, perfCost, surface, style, glyph, summary] = seed;
  const id = `kpi-${idSlug}`;
  return {
    id,
    widgetId: `bulk-widget-${(index + 1).toString().padStart(4, "0")}`,
    title,
    summary,
    thumbnail: glyph,
    tags: [intent, shape, maturity.toLowerCase().replace(" ", "-")],
    maturity,
    perfCost,
    intents: [intent],
    dataShapes: [shape],
    surfaces: [surface],
    styles: [style],
    snippet: snippetFor(id, title),
    previewMock: payloadFromShape(shape, index, title)
  };
}

export const KPI_BULK_CATALOG: readonly KpiCatalogItem[] = BULK_SEEDS.map(toCatalogItem);

export function listBulkCatalogByMaturity(maturity: Maturity): readonly KpiCatalogItem[] {
  return KPI_BULK_CATALOG.filter((item) => item.maturity === maturity);
}

export function listBulkCatalogByIntent(intent: KpiIntent): readonly KpiCatalogItem[] {
  return KPI_BULK_CATALOG.filter((item) => item.intents.includes(intent));
}

export function pickBulkCatalogSlice(offset: number, size: number): readonly KpiCatalogItem[] {
  const safeOffset = Number.isFinite(offset) ? Math.max(0, Math.trunc(offset)) : 0;
  const safeSize = Number.isFinite(size) ? Math.max(1, Math.trunc(size)) : 24;
  return KPI_BULK_CATALOG.slice(safeOffset, safeOffset + safeSize);
}
